<?php require '_layout.php'; $pdo=db();$rows=$pdo->query("SELECT o.*,c.name,c.phone,c.address FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.id DESC")->fetchAll();$statuses=['Menunggu Konfirmasi','Dikonfirmasi','Sedang Dikerjakan','Selesai','Dibatalkan']; admin_header('Kelola Pesanan','orders'); if(isset($_GET['ok'])): ?><div class="notice success">Status pesanan berhasil diperbarui.</div><?php endif; ?>
<div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Kode</th><th>Pelanggan</th><th>Kontak & Alamat</th><th>Layanan</th><th>Tanggal</th><th>Detail</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['order_code']) ?></td><td><?= e($r['name']) ?></td><td><?= e($r['phone']) ?><br><?= e($r['address']) ?></td><td><?= e($r['service']) ?></td><td><?= e($r['service_date']) ?></td><td><?= e($r['details']) ?></td><td><?= e($r['status']) ?></td><td><form class="inline-form" method="post" action="update-status.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status"><?php foreach($statuses as $s): ?><option <?= $r['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button class="small-btn">Simpan</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8">Belum ada pesanan.</td></tr><?php endif; ?></tbody></table></div></div><?php admin_footer(); ?>
